// pages/login.page.ts
// Generated by QA-AI-Framework — Playwright Automation Agent
// Module: Authentication & Access (AUTH)
// Application: IGZ Marquis Hunting App ("RanchOps Pro")
//
// Live DOM verification: docs/dom-snapshots/auth.json (2026-11-03).
// Discrepancy vs. documentation: the authenticated password-change flow is reached via a
// header profile-menu item literally labeled "Change Password" (route /change-password),
// not "Reset Password" as RequirementAnalysis.md/TC_AUTH_007-010/TC_UI_AUTH_017 assumed;
// and the unauthenticated flow is an OTP-code flow ("Send Reset Code"), not an emailed link.
// See docs/dom-snapshots/auth.json for full detail.

import { expect, Locator, Page } from '@playwright/test';
import BasePage from '../Framework/src/pages/base.page';
import { HTMLSubStepLogger } from '../Framework/src/utils/htmlSubStepLogger';
import { ConfigurationManager } from '../Framework/src/config/ConfigurationManager';

export class LoginPage extends BasePage {
  constructor(page: Page, subStepLogger?: HTMLSubStepLogger) {
    super(page, subStepLogger);
  }

  // ==================== Locators ====================

  // -- Landing page --
  get loginToPortalButton(): Locator {
    return this.page.getByRole('button', { name: 'Login to Portal' });
  }

  // -- Login page (/login) --
  get loginHeading(): Locator {
    return this.page.getByRole('heading', { name: 'RanchOps Pro' });
  }

  get signInSubtitleText(): Locator {
    return this.page.getByText('Sign in to your account');
  }

  get emailInput(): Locator {
    return this.page.getByRole('textbox', { name: 'Email', exact: true });
  }

  get passwordInput(): Locator {
    return this.page.getByRole('textbox', { name: 'Password', exact: true });
  }

  get passwordShowToggleButton(): Locator {
    return this.page.getByRole('button', { name: 'Show password' }).first();
  }

  get signInButton(): Locator {
    return this.page.getByRole('button', { name: 'Sign In' });
  }

  get forgotResetPasswordButton(): Locator {
    return this.page.getByRole('button', { name: 'Forgot/Reset Password?' });
  }

  get loginErrorBanner(): Locator {
    return this.page.getByRole('alert');
  }

  // -- Forgot Password screen (/forgot-password) --
  get forgotPasswordHeading(): Locator {
    return this.page.getByRole('heading', { name: 'Forgot Password?' });
  }

  get forgotPasswordEmailInput(): Locator {
    return this.page.getByRole('textbox', { name: 'Email Address' });
  }

  get sendResetCodeButton(): Locator {
    return this.page.getByRole('button', { name: 'Send Reset Code' });
  }

  get backToLoginButton(): Locator {
    return this.page.getByRole('button', { name: 'Back to Login' });
  }

  get forgotPasswordMandatoryIndicator(): Locator {
    return this.page.locator('label:has-text("Email") >> text="*"');
  }

  // -- Header / Profile menu (authenticated) --
  get profileMenuButton(): Locator {
    return this.page.getByRole('banner').getByRole('button').last();
  }

  get changePasswordMenuItem(): Locator {
    return this.page.getByRole('menuitem', { name: 'Change Password' });
  }

  get logoutMenuItem(): Locator {
    return this.page.getByRole('menuitem', { name: 'Log out' });
  }

  // -- Change Password screen (/change-password) --
  get changePasswordHeading(): Locator {
    return this.page.getByRole('heading', { name: 'Change Password' });
  }

  get currentPasswordInput(): Locator {
    return this.page.getByRole('textbox', { name: 'Current Password' });
  }

  get newPasswordInput(): Locator {
    return this.page.getByRole('textbox', { name: 'New Password' });
  }

  get confirmNewPasswordInput(): Locator {
    return this.page.getByRole('textbox', { name: 'Confirm New Password' });
  }

  get newPasswordHelperText(): Locator {
    return this.page.getByText('Min 8 characters with uppercase, lowercase, number, and special character');
  }

  get changePasswordSubmitButton(): Locator {
    return this.page.getByRole('button', { name: 'Change Password', exact: true });
  }

  get changePasswordCancelButton(): Locator {
    return this.page.getByRole('button', { name: 'Cancel' });
  }

  get toastMessage(): Locator {
    return this.page.locator('[role="status"], [data-sonner-toast], .toast').first();
  }

  // ==================== Validations ====================

  async isLoginPageDisplayed(): Promise<boolean> {
    return (await this.emailInput.isVisible()) && (await this.passwordInput.isVisible()) && (await this.signInButton.isVisible());
  }

  async isForgotPasswordScreenDisplayed(): Promise<boolean> {
    return this.forgotPasswordHeading.isVisible();
  }

  async isChangePasswordScreenDisplayed(): Promise<boolean> {
    return this.changePasswordHeading.isVisible();
  }

  async isPasswordMasked(locator: Locator): Promise<boolean> {
    return (await locator.getAttribute('type')) === 'password';
  }

  async assertDashboardLoaded(): Promise<void> {
    // Post-login landing route is role-dependent: Super Admin/Ranch Admin land on
    // /dashboard, Guide lands directly on /bookings.
    await expect(this.page).toHaveURL(/\/(dashboard|bookings)/, { timeout: 30000 });
  }

  async assertRedirectedToLogin(): Promise<void> {
    await expect(this.page).toHaveURL(/\/login/, { timeout: 30000 });
  }

  async assertLoginErrorVisible(): Promise<void> {
    await expect(this.loginErrorBanner.or(this.toastMessage)).toBeVisible();
  }

  async assertValidationErrorFor(fieldLocator: Locator): Promise<void> {
    const container = this.page.locator('div').filter({ has: fieldLocator }).last();
    await expect(container.getByText(/required|invalid|must/i)).toBeVisible();
  }

  // ==================== Actions ====================

  /**
   * Routes to the Login page the only supported way: root -> "Login to Portal" -> app
   * resolves /login or /dashboard depending on existing session. Deep-linking to /login
   * directly 404s because this is a client-side-routed SPA.
   */
  async navigateToLogin(): Promise<void> {
    await this.logInfo('Navigating to application root');
    await this.page.goto(ConfigurationManager.config().baseUrl);
    await this.withHeal(this.loginToPortalButton, (l) => l.click(), 'Login to Portal Button');
    await this.waitForLoadingToComplete();
  }

  async login(email: string, password: string): Promise<void> {
    await this.logInfo(`Logging in as ${email}`);
    await this.withHeal(this.emailInput, (l) => l.fill(email), 'Email Input');
    await this.withHeal(this.passwordInput, (l) => l.fill(password), 'Password Input');
    await this.withHeal(this.signInButton, (l) => l.click(), 'Sign In Button');
    await this.logSuccess('Sign In submitted');
  }

  async togglePasswordVisibility(): Promise<void> {
    await this.withHeal(this.passwordShowToggleButton, (l) => l.click(), 'Show Password Toggle');
  }

  async clickForgotResetPassword(): Promise<void> {
    await this.withHeal(this.forgotResetPasswordButton, (l) => l.click(), 'Forgot/Reset Password Link');
  }

  async submitForgotPassword(email: string): Promise<void> {
    await this.logInfo(`Requesting password reset code for ${email}`);
    await this.withHeal(this.forgotPasswordEmailInput, (l) => l.fill(email), 'Forgot Password Email Input');
    await this.withHeal(this.sendResetCodeButton, (l) => l.click(), 'Send Reset Code Button');
  }

  async clickBackToLogin(): Promise<void> {
    await this.withHeal(this.backToLoginButton, (l) => l.click(), 'Back to Login Button');
  }

  async openProfileMenu(): Promise<void> {
    await this.withHeal(this.profileMenuButton, (l) => l.click(), 'Profile Menu Button');
  }

  async navigateToChangePassword(): Promise<void> {
    await this.openProfileMenu();
    await this.withHeal(this.changePasswordMenuItem, (l) => l.click(), 'Change Password Menu Item');
    await this.waitForLoadingToComplete();
  }

  async changePassword(currentPassword: string, newPassword: string, confirmPassword: string): Promise<void> {
    await this.logInfo('Submitting authenticated password change');
    await this.withHeal(this.currentPasswordInput, (l) => l.fill(currentPassword), 'Current Password Input');
    await this.withHeal(this.newPasswordInput, (l) => l.fill(newPassword), 'New Password Input');
    await this.withHeal(this.confirmNewPasswordInput, (l) => l.fill(confirmPassword), 'Confirm New Password Input');
    await this.withHeal(this.changePasswordSubmitButton, (l) => l.click(), 'Change Password Submit Button');
  }

  async cancelChangePassword(): Promise<void> {
    await this.withHeal(this.changePasswordCancelButton, (l) => l.click(), 'Change Password Cancel Button');
  }

  async logout(): Promise<void> {
    await this.openProfileMenu();
    await this.withHeal(this.logoutMenuItem, (l) => l.click(), 'Log out Menu Item');
  }
}
